  474:     uint32_t tick = 0U;
  475: 
  476:     for (;;) {
  477:         vTaskDelay(pdMS_TO_TICKS(CONFIG_EMULATOR_TICK_MS));
  478:         ++tick;
  479: #ifdef CONFIG_EMULATOR_BURST_UPDATES
  480:         const uint8_t iterations = EMULATOR_BURST_COUNT;
  481: #else
  482:         const uint8_t iterations = 1U;
  483: #endif
  484: #ifdef CONFIG_EMULATOR_INJECT_INVALID_VALUES
  485:         const bool inject_invalid = (tick % 6U) == 0U;
  486: #else
  487:         const bool inject_invalid = false;
  488: #endif
  489:         if (!esp_zigbee_lock_acquire(pdMS_TO_TICKS(100))) {
  490:             ESP_LOGW(TAG, "emulation update lock timeout");
  491:             continue;
  492:         }
