  494:         for (uint8_t i = 0U; i < iterations; ++i) {
  495: #if CONFIG_EMULATOR_PROFILE_TEMP_HUM || CONFIG_EMULATOR_PROFILE_MIXED ||     CONFIG_EMULATOR_PROFILE_SLEEPY_ENV_BATTERY
  496:             temperature = (int16_t)(temperature + temperature_step);
