  519:                 battery_percentage = (uint8_t)(battery_percentage - 2U);
  520:             } else {
  521:                 battery_percentage = 180U;
  522:             }
  523:             battery_voltage = (uint8_t)(27U + ((battery_percentage - 120U) / 20U));
  524:             (void)set_server_attr(
  525:                 EMULATOR_ENV_ENDPOINT, EMULATOR_CLUSTER_POWER_CONFIG,
  526:                 EMULATOR_ATTR_BATTERY_VOLTAGE, &battery_voltage);
  527:             (void)set_server_attr(
  528:                 EMULATOR_ENV_ENDPOINT, EMULATOR_CLUSTER_POWER_CONFIG,
  529:                 EMULATOR_ATTR_BATTERY_PERCENTAGE_REMAINING, &battery_percentage);
  530: #endif
  531: #endif
